(function(){
  var g = gcd(scope.a_base, scope.b_base);
  var a_simp = scope.a_base / g;
  var b_simp = scope.b_base / g;
  var k = scope.k;
  var a = a_simp * k;
  var b = b_simp * k;
  var ans = a_simp + ':' + b_simp;
  var calc_str = b_simp === 1 ? ('' + a_simp) : ('\\frac{' + a_simp + '}{' + b_simp + '}');
  return { a: a, b: b, a_simp: a_simp, b_simp: b_simp, ans: ans, calc_str: calc_str };
})()

(function(){
  function gcd3(x, y, z) { return gcd(x, gcd(y, z)); }
  var g_raw = gcd3(scope.a_raw, scope.b_raw, scope.c_raw);
  var a_base = scope.a_raw / g_raw;
  var b_base = scope.b_raw / g_raw;
  var c_base = scope.c_raw / g_raw;
  var k = scope.k;
  var a = a_base * k;
  var b = b_base * k;
  var c = c_base * k;
  var g = k * g_raw;
  var ans = a_base + ':' + b_base + ':' + c_base;
  return { a: a, b: b, c: c, g: g, a_base: a_base, b_base: b_base, c_base: c_base, ans: ans };
})()

(function(){
  var a_count = scope.ratio_a * scope.multiplier;
  var b_count = scope.ratio_b * scope.multiplier;
  return { a_count: a_count, b_count: b_count };
})()

(function(){
  var types = [
    { text: '\\$2.50 : 50\\text{\\u00a2}', val1: 250, val2: 50, unit1: '\\$2.50 = 250\\text{\\u00a2}', unit2: '50\\text{\\u00a2}' },
    { text: '80\\text{ cm} : 1.2\\text{ m}', val1: 80, val2: 120, unit1: '80\\text{ cm}', unit2: '1.2\\text{ m} = 120\\text{ cm}' },
    { text: '600\\text{ m} : 2\\text{ km}', val1: 600, val2: 2000, unit1: '600\\text{ m}', unit2: '2\\text{ km} = 2000\\text{ m}' },
    { text: '1.5\\text{ kg} : 250\\text{ g}', val1: 1500, val2: 250, unit1: '1.5\\text{ kg} = 1500\\text{ g}', unit2: '250\\text{ g}' },
    { text: '1.4\\text{ l} : 600\\text{ cm}^3', val1: 1400, val2: 600, unit1: '1.4\\text{ l} = 1400\\text{ cm}^3', unit2: '600\\text{ cm}^3' },
    { text: '1.25\\text{ h} : 40\\text{ min}', val1: 75, val2: 40, unit1: '1.25\\text{ h} = 75\\text{ min}', unit2: '40\\text{ min}' },
    { text: '30\\text{ s} : 1.5\\text{ min}', val1: 30, val2: 90, unit1: '30\\text{ s}', unit2: '1.5\\text{ min} = 90\\text{ s}' }
  ];
  var item = types[scope.unit_type % types.length];
  var g = gcd(item.val1, item.val2);
  var s1 = item.val1 / g;
  var s2 = item.val2 / g;
  var ans = s1 + ':' + s2;
  var calc_str = s2 === 1 ? ('' + s1) : ('\\frac{' + s1 + '}{' + s2 + '}');
  return { origText: item.text, val1: item.val1, val2: item.val2, unit1: item.unit1, unit2: item.unit2, s1: s1, s2: s2, ans: ans, calc_str: calc_str };
})()

