(function(){
  var r1 = scope.r1, r2 = scope.r2, r3 = scope.r3;
  var g = gcd(r1, gcd(r2, r3));
  r1 = r1 / g; r2 = r2 / g; r3 = r3 / g;
  var mult = scope.multiplier;
  var yellow = r1 * mult;
  var white = r2 * mult;
  var grey = r3 * mult;
  var ans = white + ', ' + grey;
  return { r1: r1, r2: r2, r3: r3, mult: mult, yellow: yellow, white: white, grey: grey, ans: ans };
})()
